/**
 * The service worker that lets a card open again without a connection, as
 * source text generated by the build (see vite.config.ts). Pure: no DOM, no Node.
 *
 * Privacy: `sw.js` is a public file, so it must never list pages. Only shared,
 * non-identifying files are precached. The page a visitor actually opens, and
 * its vCard, are cached on that visitor's device when they open it.
 */

/** Shared files worth precaching: script, stylesheet and fonts, plus the favicon. */
export function selectPrecache(builtFiles: readonly string[]): string[] {
  const shared = builtFiles.filter((file) => /\.(js|css|woff2)$/.test(file) && file !== 'sw.js');
  return [...new Set([...shared, 'favicon.svg'])].sort();
}

/** Short stable hash (FNV-1a, twice with different seeds) for the cache name. */
function hash(text: string): string {
  const fnv = (seed: number): string => {
    let value = seed;
    for (let index = 0; index < text.length; index++) {
      value ^= text.charCodeAt(index);
      value = Math.imul(value, 0x01000193);
    }
    return (value >>> 0).toString(16).padStart(8, '0');
  };
  return fnv(0x811c9dc5) + fnv(0x1b873593);
}

/**
 * The worker's behaviour:
 * - shared files (`precache`) are stored at install and served cache-first;
 * - pages and vCards are network-first with a bounded wait, falling back to
 *   the copy cached when the visitor last opened them, so a redeploy reaches
 *   returning visitors and a venue with no signal still works;
 * - only successful, same-origin, non-redirected responses are ever stored;
 * - an address never opened before fails with a plain offline message. It is
 *   never answered with some other page;
 * - each build has its own cache. On activation the pages a visitor had are
 *   fetched again into the new cache before the old one is deleted, so a page
 *   is never left pointing at files that no longer exist.
 */
const WORKER_BODY = String.raw`
const NETWORK_WAIT_MS = 3000;
const isPage = (url) => url.pathname.endsWith('/') || url.pathname.endsWith('.html');
const isPersonal = (url) => isPage(url) || url.pathname.endsWith('.vcf');
const storable = (response) => response.ok && response.type === 'basic' && !response.redirected;
const scopeUrl = (path) => new URL(path, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((path) => new Request(scopeUrl(path), { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

// Stores a fresh copy of a page or vCard. Failures are ignored: the old copy,
// if any, stays until the next successful visit.
async function refresh(url) {
  try {
    const response = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
    if (storable(response)) await (await caches.open(CACHE)).put(url, response);
  } catch {}
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const old = (await caches.keys()).filter((name) => name.startsWith('ikizen-') && name !== CACHE);
    // Carry over what this visitor had opened, re-fetched so it matches this build.
    for (const name of old) {
      const requests = await (await caches.open(name)).keys();
      await Promise.all(requests.filter((request) => isPersonal(new URL(request.url))).map((request) => refresh(request.url)));
    }
    await Promise.all(old.map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

// The page asks for itself and its vCard to be kept, since its first load
// happened before this worker controlled it.
self.addEventListener('message', (event) => {
  const urls = event.data && event.data.type === 'keep' ? event.data.urls : [];
  const own = urls.filter((url) => typeof url === 'string' && new URL(url, self.location.href).origin === self.location.origin);
  event.waitUntil(Promise.all(own.map((url) => refresh(new URL(url, self.location.href).href))));
});

const offline = () => new Response('Sin conexión. Esta página no está guardada en este dispositivo.', {
  status: 503,
  statusText: 'Offline',
  headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store' },
});

// Network first, but never longer than NETWORK_WAIT_MS when a saved copy exists.
async function networkFirst(event) {
  const cache = await caches.open(CACHE);
  const key = new URL(event.request.url);
  key.search = '';
  key.hash = '';
  const saved = await cache.match(key.href);

  const network = fetch(event.request).then((response) => {
    if (storable(response)) event.waitUntil(cache.put(key.href, response.clone()));
    return response;
  });
  if (!saved) return network.catch(offline);

  const timeout = new Promise((resolve) => setTimeout(() => resolve(saved), NETWORK_WAIT_MS));
  // A late answer still updates the saved copy for next time.
  event.waitUntil(network.catch(() => undefined));
  return Promise.race([network.catch(() => saved), timeout]);
}

async function cacheFirst(event) {
  const cache = await caches.open(CACHE);
  const saved = await cache.match(event.request);
  if (saved) return saved;
  const response = await fetch(event.request);
  if (storable(response)) event.waitUntil(cache.put(event.request, response.clone()));
  return response;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;

  if (request.mode === 'navigate' || isPersonal(url)) {
    event.respondWith(networkFirst(event));
  } else if (PRECACHE.some((path) => scopeUrl(path) === url.href) || /\/assets\/[^/]+\.(js|css|woff2)$/.test(url.pathname)) {
    event.respondWith(cacheFirst(event));
  }
  // Anything else (link-preview images, for one) goes straight to the network.
});
`;

/** Source of `sw.js` for a build whose shared files are `precache`. */
export function buildServiceWorker(precache: readonly string[]): string {
  const list = JSON.stringify([...precache]);
  const version = hash(list + WORKER_BODY);
  return (
    '// Generated by the build from src/offline.ts. Do not edit.\n' +
    `const CACHE = ${JSON.stringify(`ikizen-${version}`)};\n` +
    `const PRECACHE = ${list};\n` +
    WORKER_BODY
  );
}
